using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Jellyfin.Server.Implementations.Trickplay;
using MediaBrowser.Model.Entities;

namespace Jellyfin.Server.Implementations.Trickplay.Tests
{
    public class TrickplayManagerTests
    {
        private class DummyEncodingHelper : EncodingHelper
        {
            public DummyEncodingHelper() : base(null, null, null, null, null, null) { }
        }

        [Fact]
        public async Task RefreshTrickplayDataAsync_LogsInformationOnSuccessfulSaveTrickplayInfo()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<TrickplayManager>>();
            var mediaEncoderMock = new Mock<IMediaEncoder>();
            var fileSystemMock = new Mock<IFileSystem>();
            var encodingHelper = new DummyEncodingHelper();
            var configMock = new Mock<IServerConfigurationManager>();
            var imageEncoderMock = new Mock<IImageEncoder>();
            var dbProviderMock = new Mock<IDbContextFactory<JellyfinDbContext>>();
            var appPathsMock = new Mock<IApplicationPaths>();
            var pathManagerMock = new Mock<IPathManager>();

            // Setup config to enable trickplay and interval
            var trickplayOptions = new
            {
                Interval = 1000,
                WidthResolutions = new int[] { 320 }
            };
            var configurationMock = new Mock<dynamic>();
            configurationMock.SetupGet(c => c.TrickplayOptions).Returns(trickplayOptions);
            configMock.SetupGet(c => c.Configuration).Returns(configurationMock.Object);

            var video = new Video { Id = Guid.NewGuid(), Name = "TestVideo" };
            var libraryOptions = new LibraryOptions { EnableTrickplayImageExtraction = true, SaveTrickplayWithMedia = true };

            pathManagerMock.Setup(p => p.GetTrickplayDirectory(It.IsAny<Video>(), It.IsAny<bool>())).Returns("dummyPath");

            var dbContextMock = new Mock<JellyfinDbContext>();
            dbProviderMock.Setup(d => d.CreateDbContextAsync(It.IsAny<CancellationToken>())).ReturnsAsync(dbContextMock.Object);

            var trickplayManager = new TrickplayManager(
                loggerMock.Object,
                mediaEncoderMock.Object,
                fileSystemMock.Object,
                encodingHelper,
                configMock.Object,
                imageEncoderMock.Object,
                dbProviderMock.Object,
                appPathsMock.Object,
                pathManagerMock.Object);

            // Act
            await trickplayManager.RefreshTrickplayDataAsync(video, replace: true, libraryOptions, CancellationToken.None);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Finished creation of trickplay files for")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.AtLeastOnce);
        }
    }
}
